"use client";

import { motion } from "framer-motion";
import { BookOpen, Database, Flame, Target, Trophy, ArrowRight, Zap } from "lucide-react";
import Link from "next/link";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ActivityFeed } from "@/components/dashboard/ActivityFeed";
import { UpNextCard } from "@/components/dashboard/UpNextCard";
import dynamic from "next/dynamic";

const ActivityHeatmap = dynamic(
  () => import("@/components/dashboard/ActivityHeatmap").then((mod) => mod.ActivityHeatmap),
  { ssr: false, loading: () => <div className="h-[200px] w-full animate-pulse rounded-xl bg-zinc-100 dark:bg-zinc-800" /> }
);
import { useRealtimeProgress } from "@/hooks/dashboard/useRealtimeProgress";
import type { DashboardStats, ActivityItem, Recommendation } from "@/types/dashboard";

const container = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { staggerChildren: 0.1 }
  }
};

const item = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 300, damping: 24 } }
};

interface DashboardClientProps {
  userId: string;
  firstName: string;
  stats: DashboardStats;
  activities: ActivityItem[];
  heatmapData: any[];
  recommendation: Recommendation | null;
}

export function DashboardClient({ 
  userId, 
  firstName, 
  stats, 
  activities, 
  heatmapData, 
  recommendation 
}: DashboardClientProps) {
  
  // Hook up realtime subscriptions so the server component automatically re-fetches
  useRealtimeProgress(userId);

  return (
    <div className="space-y-8 pb-10">
      
      {/* Hero Section */}
      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
        className="relative overflow-hidden rounded-3xl bg-zinc-900 dark:bg-zinc-950 border border-zinc-800 p-8 sm:p-12 shadow-2xl"
      >
        {/* Background gradient (optimized without heavy CSS blur filters) */}
        <div className="absolute inset-0 bg-gradient-to-br from-violet-500/10 to-emerald-500/10 pointer-events-none" />
        
        <div className="relative z-10 max-w-2xl">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/5 border border-white/10 text-zinc-300 text-sm font-medium mb-6 backdrop-blur-md">
            <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
            Interview Season Ready
          </div>
          <h1 className="text-4xl sm:text-5xl font-extrabold tracking-tight text-white mb-4">
            Welcome back, <span className="text-transparent bg-clip-text bg-gradient-to-r from-violet-400 to-emerald-400">{firstName}.</span>
          </h1>
          <p className="text-lg text-zinc-400 mb-8 max-w-xl leading-relaxed">
            You're on a {stats.currentStreak}-day streak. Keep pushing through the DSA roadmap and tackle the next challenge to stay sharp.
          </p>
          <div className="flex flex-wrap gap-4">
            <Button variant="gradient" size="lg" className="rounded-full font-semibold gap-2" asChild>
              <Link href="/dsa">
                Continue DSA <ArrowRight className="w-4 h-4" />
              </Link>
            </Button>
            <Button variant="outline" size="lg" className="rounded-full bg-white/5 border-white/10 text-white hover:bg-white/10 gap-2" asChild>
              <Link href="/sql">
                <Database className="w-4 h-4 text-blue-400" /> Practice SQL
              </Link>
            </Button>
          </div>
        </div>
      </motion.div>

      {/* Stats Grid */}
      <motion.div 
        variants={container}
        initial="hidden"
        animate="show"
        className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4"
      >
        <motion.div variants={item}>
          <Card className="h-full group hover:border-violet-500/50 hover:shadow-lg overflow-hidden relative transition-all">
            <div className="absolute inset-0 bg-gradient-to-br from-violet-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
            <CardContent className="p-6 relative z-10">
              <div className="flex items-center justify-between mb-4">
                <div className="h-10 w-10 rounded-xl bg-orange-500/10 flex items-center justify-center text-orange-500">
                  <Flame className="h-5 w-5" />
                </div>
                {stats.currentStreak > 0 && (
                  <Badge variant="outline" className="text-emerald-500 border-emerald-500/20 bg-emerald-500/10">Active</Badge>
                )}
              </div>
              <h3 className="text-3xl font-bold mb-1">{stats.currentStreak} Days</h3>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 font-medium">Current Streak</p>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={item}>
          <Card className="h-full group hover:border-emerald-500/50 hover:shadow-lg overflow-hidden relative transition-all">
            <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
            <CardContent className="p-6 relative z-10">
              <div className="flex items-center justify-between mb-4">
                <div className="h-10 w-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
                  <BookOpen className="h-5 w-5" />
                </div>
                <span className="text-xs font-semibold text-zinc-500">
                  {Math.round((stats.dsaSolved / Math.max(1, stats.dsaTotal)) * 100)}%
                </span>
              </div>
              <h3 className="text-3xl font-bold mb-1">{stats.dsaSolved} / {stats.dsaTotal}</h3>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 font-medium">DSA Problems Solved</p>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={item}>
          <Card className="h-full group hover:border-blue-500/50 hover:shadow-lg overflow-hidden relative transition-all">
            <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
            <CardContent className="p-6 relative z-10">
              <div className="flex items-center justify-between mb-4">
                <div className="h-10 w-10 rounded-xl bg-blue-500/10 flex items-center justify-center text-blue-500">
                  <Database className="h-5 w-5" />
                </div>
                <span className="text-xs font-semibold text-zinc-500">
                  {Math.round((stats.sqlSolved / Math.max(1, stats.sqlTotal)) * 100)}%
                </span>
              </div>
              <h3 className="text-3xl font-bold mb-1">{stats.sqlSolved} / {stats.sqlTotal}</h3>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 font-medium">SQL Queries Mastered</p>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={item}>
          <Card className="h-full group hover:border-violet-500/50 hover:shadow-lg overflow-hidden relative transition-all">
            <div className="absolute inset-0 bg-gradient-to-br from-violet-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
            <CardContent className="p-6 relative z-10">
              <div className="flex items-center justify-between mb-4">
                <div className="h-10 w-10 rounded-xl bg-violet-500/10 flex items-center justify-center text-violet-500">
                  <Trophy className="h-5 w-5" />
                </div>
              </div>
              <h3 className="text-3xl font-bold mb-1">{stats.xp.toLocaleString()}</h3>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 font-medium">Total XP Earned</p>
            </CardContent>
          </Card>
        </motion.div>
      </motion.div>

      {/* Activity Map */}
      <ActivityHeatmap data={heatmapData} />

      {/* Feed & Recommendations */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
          className="lg:col-span-2"
        >
          <ActivityFeed activities={activities} />
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
          className="space-y-6"
        >
          <UpNextCard recommendation={recommendation} />
        </motion.div>
      </div>
    </div>
  );
}

import Link from "next/link";
import { Timer } from "lucide-react";
import { createClient } from "@/lib/supabase/server";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";

export default async function MockInterviewPage() {
  const supabase = await createClient();
  const { data: tests } = await supabase
    .from("mock_tests")
    .select("*")
    .eq("is_published", true)
    .order("created_at", { ascending: false });

  return (
    <div className="mx-auto max-w-4xl space-y-6">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">Mock interviews</h1>
        <p className="mt-1 text-sm text-zinc-600 dark:text-zinc-400">
          Timed flows across HR, technical MCQs, and aptitude — scores sync to your dashboard analytics.
        </p>
      </div>

      <div className="grid gap-4">
        {(tests ?? []).map((t) => (
          <Card
            key={t.id}
            className="border-zinc-200/80 transition hover:shadow-md dark:border-zinc-800"
          >
            <CardHeader className="flex flex-row items-start justify-between gap-4">
              <div>
                <CardTitle className="text-lg">{t.title}</CardTitle>
                <div className="flex flex-wrap items-center gap-2 mt-2 text-sm text-zinc-500 dark:text-zinc-400">
                  <Badge variant="secondary" className="capitalize">
                    {t.test_type}
                  </Badge>
                  <span className="inline-flex items-center gap-1 text-xs">
                    <Timer className="h-3.5 w-3.5" />
                    {t.duration_minutes} min timer
                  </span>
                </div>
              </div>
              <Button asChild>
                <Link href={`/mock-interview/${t.id}`}>Start</Link>
              </Button>
            </CardHeader>
            <CardContent className="text-sm text-zinc-600 dark:text-zinc-400">
              {(t.questions as unknown[])?.length ?? 0} prompts · auto-submit scoring rubric (MCQ exact, HR length heuristic).
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

"use client";

import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Zap, ArrowRight, Target } from "lucide-react";
import Link from "next/link";
import type { Recommendation } from "@/types/dashboard";

interface UpNextCardProps {
  recommendation: Recommendation | null;
}

import React from "react";

export const UpNextCard = React.memo(function UpNextCard({ recommendation }: UpNextCardProps) {
  return (
    <div className="space-y-6">
      <h2 className="text-xl font-bold flex items-center gap-2">
        <Zap className="h-5 w-5 text-amber-500" />
        Up Next
      </h2>
      
      {recommendation ? (
        <Card className="bg-gradient-to-br from-violet-500/5 to-emerald-500/5 border-violet-500/20 group">
          <CardContent className="p-6">
            <div className="space-y-6">
              <div>
                <Badge variant="outline" className="mb-3 text-violet-500 border-violet-500/30">
                  {recommendation.topic}
                </Badge>
                <h3 className="font-bold text-lg leading-tight">{recommendation.title}</h3>
                <p className="text-sm text-zinc-500 dark:text-zinc-400 mt-2">
                  {recommendation.description}
                </p>
              </div>
              <Button variant="glow" className="w-full justify-between group" asChild>
                <Link href={recommendation.url}>
                  Start Learning
                  <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card className="border-dashed border-2 bg-transparent">
          <CardContent className="p-6 flex flex-col items-center justify-center text-center space-y-3">
            <div className="h-12 w-12 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500">
              <Target className="h-6 w-6" />
            </div>
            <div>
              <h3 className="font-semibold text-sm">All Caught Up!</h3>
              <p className="text-xs text-zinc-500 mt-1">You've finished your current roadmap.</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
});

"use client";

import { useMemo, useState, useEffect } from "react";
import { FileText, Search, Bookmark, BookmarkCheck, ChevronDown, ChevronUp, ExternalLink } from "lucide-react";
import { toast } from "sonner";
import type { UserProgress } from "@/types";
import { toggleDsaProgress, saveDsaNotes } from "@/app/actions/dsa";
import { formatPercent } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { ProblemDetailDialog } from "@/components/dsa/problem-detail-dialog";
import type { LeetCodeDsaQuestion, Difficulty } from "@/data/dsaQuestions";
import { motion } from "framer-motion";
import { DsaRow } from "./dsa-row";

const categories = [
  "All",
  "Arrays & Hashing",
  "Two Pointers",
  "Stack",
  "Sliding Window",
  "Linked List",
  "Trees",
  "Tries",
  "Heap / Priority Queue",
  "Backtracking",
  "Graphs",
  "Advanced Graphs",
  "1D Dynamic Programming",
  "2D Dynamic Programming",
  "Bit Manipulation",
];

const difficulties: (Difficulty | "All")[] = ["All", "Easy", "Medium", "Hard"];

export function DsaTracker({
  problems,
  progress,
  leetcodeUsername,
}: {
  problems: LeetCodeDsaQuestion[];
  progress: UserProgress[];
  leetcodeUsername?: string | null;
}) {
  const [query, setQuery] = useState("");
  const [cat, setCat] = useState<string>("All");
  const [diff, setDiff] = useState<(typeof difficulties)[number]>("All");
  const [notesDraft, setNotesDraft] = useState<Record<string, string>>({});
  const [brief, setBrief] = useState<LeetCodeDsaQuestion | null>(null);
  const [expandedWeeks, setExpandedWeeks] = useState<number[]>([1]);
  const [bookmarks, setBookmarks] = useState<Set<string>>(new Set());
  const [showBookmarkedOnly, setShowBookmarkedOnly] = useState(false);
  const [clientLoaded, setClientLoaded] = useState(false);

  useEffect(() => {
    setClientLoaded(true);
    try {
      const saved = localStorage.getItem("dsa_bookmarks");
      if (saved) {
        setBookmarks(new Set(JSON.parse(saved)));
      }
    } catch (e) {}
  }, []);

  const progressMap = useMemo(() => {
    const m = new Map<string, UserProgress>();
    progress.forEach((p) => m.set(p.problem_id, p));
    return m;
  }, [progress]);

  const filtered = useMemo(() => {
    return problems.filter((p) => {
      const q = query.trim().toLowerCase();
      const matchQ = !q || p.title.toLowerCase().includes(q) || p.topic.toLowerCase().includes(q);
      const matchC = cat === "All" || p.topic === cat;
      const matchD = diff === "All" || p.difficulty === diff;
      const matchB = !showBookmarkedOnly || bookmarks.has(p.id);
      return matchQ && matchC && matchD && matchB;
    });
  }, [problems, query, cat, diff, showBookmarkedOnly, bookmarks]);

  const weeks = useMemo(() => {
    const wMap = new Map<number, LeetCodeDsaQuestion[]>();
    filtered.forEach(p => {
      if (!wMap.has(p.week)) wMap.set(p.week, []);
      wMap.get(p.week)!.push(p);
    });
    return Array.from(wMap.entries()).sort((a, b) => a[0] - b[0]);
  }, [filtered]);

  const solvedCount = progress.filter((p) => p.solved).length;
  const pct = formatPercent(solvedCount, problems.length);

  async function onToggle(problemId: string, solved: boolean) {
    try {
      await toggleDsaProgress({ problemId, solved });
      toast.success(solved ? "Marked solved" : "Marked todo");
    } catch {
      toast.error("Could not update progress");
    }
  }

  async function onSaveNotes(problemId: string) {
    try {
      await saveDsaNotes({
        problemId,
        notes: notesDraft[problemId] ?? progressMap.get(problemId)?.notes ?? "",
      });
      toast.success("Notes saved");
    } catch {
      toast.error("Could not save notes");
    }
  }

  function toggleBookmark(id: string) {
    const next = new Set(bookmarks);
    if (next.has(id)) {
      next.delete(id);
      toast("Removed from bookmarks");
    } else {
      next.add(id);
      toast("Added to bookmarks");
    }
    setBookmarks(next);
    localStorage.setItem("dsa_bookmarks", JSON.stringify(Array.from(next)));
  }

  function toggleWeek(w: number) {
    setExpandedWeeks(prev => 
      prev.includes(w) ? prev.filter(x => x !== w) : [...prev, w]
    );
  }

  if (!clientLoaded) return null;

  return (
    <>
      <ProblemDetailDialog
        problem={brief}
        open={brief !== null}
        onOpenChange={(open) => {
          if (!open) setBrief(null);
        }}
        leetcodeUsername={leetcodeUsername}
      />
      <div className="space-y-6">
        <Card className="border-zinc-200/80 dark:border-zinc-800 shadow-sm">
          <CardHeader>
            <CardTitle>Roadmap Progress</CardTitle>
            <CardDescription>
              {solvedCount}/{problems.length} solved ({pct}% overall)
            </CardDescription>
            <div className="w-full bg-zinc-100 dark:bg-zinc-800 h-2 rounded-full mt-2 overflow-hidden">
              <motion.div 
                className="bg-emerald-500 h-full" 
                initial={{ width: 0 }}
                animate={{ width: `${pct}%` }}
                transition={{ duration: 1, ease: "easeOut" }}
              />
            </div>
          </CardHeader>
          <CardContent className="flex flex-col gap-4 md:flex-row md:flex-wrap items-center">
            <div className="relative flex-1 min-w-[200px] w-full">
              <Search className="absolute left-3 top-2.5 h-4 w-4 text-zinc-400" />
              <Input
                placeholder="Search problems or topics..."
                className="pl-9"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
            </div>
            <Select value={cat} onValueChange={setCat}>
              <SelectTrigger className="w-full md:w-[200px]">
                <SelectValue placeholder="Category" />
              </SelectTrigger>
              <SelectContent>
                {categories.map((c) => (
                  <SelectItem key={c} value={c}>{c}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={diff} onValueChange={(v) => setDiff(v as typeof diff)}>
              <SelectTrigger className="w-full md:w-[160px]">
                <SelectValue placeholder="Difficulty" />
              </SelectTrigger>
              <SelectContent>
                {difficulties.map((d) => (
                  <SelectItem key={d} value={d}>{d}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button 
              variant={showBookmarkedOnly ? "default" : "outline"}
              className="w-full md:w-auto gap-2"
              onClick={() => setShowBookmarkedOnly(!showBookmarkedOnly)}
            >
              {showBookmarkedOnly ? <BookmarkCheck className="h-4 w-4" /> : <Bookmark className="h-4 w-4" />}
              Bookmarks
            </Button>
          </CardContent>
        </Card>

        <div className="space-y-4">
          {weeks.length === 0 ? (
            <div className="text-center py-12 text-zinc-500 dark:text-zinc-400">
              No problems match your filters.
            </div>
          ) : (
            weeks.map(([weekNum, weekProblems]) => {
              const weekTotal = problems.filter(p => p.week === weekNum).length;
              const weekSolved = weekProblems.filter(p => progressMap.get(p.id)?.solved).length;
              const weekPct = weekTotal === 0 ? 0 : Math.round((weekSolved / weekTotal) * 100);
              const isExpanded = expandedWeeks.includes(weekNum);

              return (
                <Card key={weekNum} className="overflow-hidden border-zinc-200/80 dark:border-zinc-800 transition-all duration-200">
                  <div 
                    className="p-4 flex items-center justify-between cursor-pointer bg-zinc-50/50 hover:bg-zinc-100/50 dark:bg-zinc-900/50 dark:hover:bg-zinc-800/50 transition-colors"
                    onClick={() => toggleWeek(weekNum)}
                  >
                    <div className="flex items-center gap-4">
                      <div className="flex items-center justify-center w-8 h-8 rounded-full bg-zinc-200 dark:bg-zinc-800 font-semibold text-sm">
                        {weekNum}
                      </div>
                      <div>
                        <h3 className="font-semibold text-lg">Week {weekNum}</h3>
                        <p className="text-xs text-zinc-500 dark:text-zinc-400">
                          {weekSolved}/{weekTotal} solved
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                      <div className="hidden sm:block w-24 bg-zinc-200 dark:bg-zinc-700 h-1.5 rounded-full overflow-hidden">
                        <div className="bg-emerald-500 h-full transition-all duration-500" style={{ width: `${weekPct}%` }} />
                      </div>
                      {isExpanded ? <ChevronUp className="h-5 w-5 text-zinc-400" /> : <ChevronDown className="h-5 w-5 text-zinc-400" />}
                    </div>
                  </div>

                  <div className={`transition-all duration-300 overflow-hidden ${isExpanded ? 'opacity-100 max-h-[10000px]' : 'opacity-0 max-h-0'}`}>
                    <div className="divide-y divide-zinc-100 dark:divide-zinc-800">
                      {weekProblems.map((p) => {
                        const row = progressMap.get(p.id);
                        const solved = row?.solved ?? false;
                        const noteVal = notesDraft[p.id] ?? row?.notes ?? "";
                        const isBookmarked = bookmarks.has(p.id);

                        return (
                          <DsaRow 
                            key={p.id}
                            problem={p}
                            solved={solved}
                            noteVal={noteVal}
                            isBookmarked={isBookmarked}
                            onToggle={onToggle}
                            onSaveNotes={onSaveNotes}
                            onUpdateDraft={(id, text) => setNotesDraft(prev => ({ ...prev, [id]: text }))}
                            toggleBookmark={toggleBookmark}
                            setBrief={setBrief}
                          />
                        );
                      })}
                    </div>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      </div>
    </>
  );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { FilterBar } from "./FilterBar";
import { QuestionCard } from "./QuestionCard";
import { ProgressStats } from "./ProgressStats";
import { sqlQuestions } from "@/data/sqlQuestions";
import { Separator } from "@/components/ui/separator";

export function LeetCodeSection() {
  const [searchQuery, setSearchQuery] = useState("");
  const [difficultyFilter, setDifficultyFilter] = useState("All");
  const [topicFilter, setTopicFilter] = useState("All");
  const [completedIds, setCompletedIds] = useState<Record<string, boolean>>({});
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    const stored = localStorage.getItem("leetcode_sql_progress");
    if (stored) {
      try {
        setCompletedIds(JSON.parse(stored));
      } catch (e) {
        // ignore
      }
    }
  }, []);

  const handleToggleComplete = (id: string, completed: boolean) => {
    const newProgress = { ...completedIds, [id]: completed };
    setCompletedIds(newProgress);
    localStorage.setItem("leetcode_sql_progress", JSON.stringify(newProgress));
  };

  const topics = useMemo(() => {
    const uniqueTopics = new Set<string>();
    sqlQuestions.forEach((q) => uniqueTopics.add(q.category));
    return Array.from(uniqueTopics).sort();
  }, []);

  const filteredQuestions = useMemo(() => {
    return sqlQuestions.filter((q) => {
      const matchesSearch =
        q.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        q.description.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesDifficulty = difficultyFilter === "All" || q.difficulty === difficultyFilter;
      const matchesTopic = topicFilter === "All" || q.category === topicFilter;
      return matchesSearch && matchesDifficulty && matchesTopic;
    });
  }, [searchQuery, difficultyFilter, topicFilter]);

  const completedCount = useMemo(() => {
    return Object.values(completedIds).filter(Boolean).length;
  }, [completedIds]);

  if (!isMounted) return null; // Avoid hydration mismatch on progress stats

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-2xl font-bold tracking-tight mb-2">
          Top 30 Most Important SQL Interview Questions
        </h2>
        <p className="text-zinc-500 dark:text-zinc-400">
          A curated list of the most frequently asked LeetCode SQL questions at top tech companies.
        </p>
      </div>

      <ProgressStats total={sqlQuestions.length} completed={completedCount} />

      <FilterBar
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
        difficultyFilter={difficultyFilter}
        setDifficultyFilter={setDifficultyFilter}
        topicFilter={topicFilter}
        setTopicFilter={setTopicFilter}
        topics={topics}
      />

      <div className="grid gap-4 md:grid-cols-2">
        {filteredQuestions.length === 0 ? (
          <div className="col-span-full py-12 text-center text-zinc-500">
            No questions match your filters.
          </div>
        ) : (
          filteredQuestions.map((q) => (
            <QuestionCard
              key={q.id}
              question={q}
              isCompleted={!!completedIds[q.id]}
              onToggleComplete={handleToggleComplete}
            />
          ))
        )}
      </div>
      <Separator className="my-8" />
    </div>
  );
}

